from collections import Counter

_PATTERNS = {
    1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
    2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
    3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
}

def transform(grid):
    counts = Counter(v for row in grid for v in row if v != 0)
    color = max(counts, key=counts.get)
    return [row[:] for row in _PATTERNS[color]]
